    updated_at timestamp(0) without time zone,
    quantity integer DEFAULT 1 NOT NULL,
    paid_at timestamp(0) without time zone,
    order_status character varying(30) DEFAULT 'pending_payment'::character varying NOT NULL,
    CONSTRAINT transactions_currency_check CHECK (((currency)::text = 'XOF'::text)),
    CONSTRAINT transactions_delivery_type_check CHECK (((delivery_type)::text = ANY ((ARRAY['pickup'::character varying, 'delivery'::character varying, 'meetup'::character varying])::text[]))),
    CONSTRAINT transactions_order_status_check CHECK (((order_status)::text = ANY ((ARRAY['pending_payment'::character varying, 'processing'::character varying, 'shipped'::character varying, 'delivered'::character varying, 'completed'::character varying, 'cancelled'::character varying, 'disputed'::character varying])::text[]))),
    CONSTRAINT transactions_payment_method_check CHECK (((payment_method)::text = ANY ((ARRAY['orange_money'::character varying, 'wave'::character varying, 'cash'::character varying])::text[]))),
    CONSTRAINT transactions_payment_status_check CHECK (((payment_status)::text = ANY ((ARRAY['pending'::character varying, 'processing'::character varying, 'completed'::character varying, 'failed'::character varying, 'refunded'::character varying])::text[]))),
    CONSTRAINT transactions_security_check_check CHECK (((security_check)::text = ANY ((ARRAY['pending'::character varying, 'passed'::character varying, 'failed'::character varying, 'manual_review'::character varying])::text[])))
);


